"Recibos de leitura: desligados, quem te escreve deixa de ver \"Lida\" nas conversas contigo e tu também deixas de o ver nas tuas. Nos grupos as tuas leituras continuam a contar para quem enviou. Visto por último e online: desligado, ninguém vê se estás online nem quando estiveste pela última vez.": "Leesbevestigingen: als ze uit staan, zien mensen die je berichten sturen niet meer \"Gelezen\" in hun gesprekken met jou, en jij ziet het ook niet meer in de jouwe. In groepen tellen je leesbevestigingen nog steeds mee voor de afzender. Laatst gezien en online: als het uit staat, kan niemand zien of je online bent of wanneer je voor het laatst online was.",
